import numpy as np

def grad(p):
    return np.array([p[0], 25 * p[1]])

def loss(p):
    return 0.5 * (p[0] ** 2 + 25 * p[1] ** 2)

def jalankan(lr, beta, langkah=50):
    p = np.array([10.0, 1.0])
    v = np.zeros(2)
    for _ in range(langkah):
        v = beta * v + grad(p)
        p = p - lr * v
    return loss(p)

print(f"{jalankan(0.02, 0.0):.4f}")
